# api shell integration (bash 3.2+). Load it with:
#   eval "$(command api shell-init bash)"
#
# Same contract as the zsh wrapper: change THIS shell for the commands that
# print shell code (those with --emit), and forward the unexported API_*
# session variables per call. Generated by `api shell-init bash`: the command
# and flag lists come from the binary itself.

# Sets _API_BIN to the real binary (not this function).
function _api::bin() {
  [[ -x "${_API_BIN-}" ]] && return 0
  _API_BIN="$(type -P api 2>/dev/null)"
  [[ -n "$_API_BIN" ]] || _API_BIN="$HOME/.local/bin/api"
  [[ -x "$_API_BIN" ]]
}

# Run the binary with the session variables forwarded (never exported).
function _api::run() {
  _api::bin || {
    echo "✗ api binary not found: put it on PATH (see: make install)" >&2
    return 127
  }
  local -a fwd=("API_BASE_URL=${API_BASE_URL-}" "API_GRAPHQL_URL=${API_GRAPHQL_URL-}"
    "API_TOKEN=${API_TOKEN-}" "API_ENV=${API_ENV-}" "API_ENV_FROM=${API_ENV_FROM-}" "API_SHIM=@CONTRACT@") # marker for `api doctor`
  local v
  for v in $(compgen -v API_TOKEN_); do
    fwd+=("$v=${!v}")
  done
  command env "${fwd[@]}" "$_API_BIN" "$@"
}

function api() {
  local -a rest=()
  local a
  for a in "$@"; do rest[${#rest[@]}]="$a"; done
  while ((${#rest[@]})); do
    case "${rest[0]}" in
    @VALUE_FLAGS@) rest=(${rest[@]+"${rest[@]:2}"}) ;;
    @BARE_FLAGS@) rest=(${rest[@]+"${rest[@]:1}"}) ;;
    *) break ;;
    esac
  done

  # Commands whose output is shell code (each has --emit).
  local -a emitting=(@EMITTING@)
  local mutating=0 e key="${rest[0]-} ${rest[1]-}"
  for e in "${emitting[@]}"; do
    [[ "$e" == "${rest[0]-}" || "$e" == "$key" ]] && mutating=1
  done
  # Help output must never be eval'd.
  for a in "$@"; do
    case "$a" in -h | --help | --emit) mutating=0 ;; esac
  done

  if ((! mutating)); then
    _api::run "$@"
    return
  fi

  local out
  out="$(_api::run "$@" --emit)" || return $?
  eval "$out"
  if [[ "${rest[0]-}" == env && ("${rest[1]-}" == load || "${rest[1]-}" == use) ]]; then
    _api::run env status
  fi
  return 0
}

# Completion script, embedded. Cobra's bash completion needs bash 4+ and the
# bash-completion package; without them the wrapper still works.
function _api::completion_script() {
  cat <<'API_COMPLETION_EOF'
@COMPLETION@
API_COMPLETION_EOF
}

if [[ $- == *i* ]] && ((BASH_VERSINFO[0] >= 4)) && declare -F _get_comp_words_by_ref >/dev/null; then
  source <(_api::completion_script)
fi
